-- Adds the prohibited areas from the official CAAI drone restriction map
-- (Information-pages Drones restricted airspace, KMZ) that aip_reference_zones
-- was missing. Compared against production on 2026-10-03: 6 of the 35
-- "אזורים אסורים לטיסת כטב\"ם קטן" polygons had no counterpart (two nature
-- reserves + the four offshore "shushan" areas).
-- Inserted as kind PROHIBITED -- how flight-rules.ts treats a ground-based
-- area where small-UAS flight is banned outright.
-- Idempotent: re-running replaces only rows carrying this source tag.
delete from aip_reference_zones where source_sheet = 'caai_drone_map_2026_09';

insert into aip_reference_zones
  (name, code, kind, altitude_text, min_altitude_ft, max_altitude_ft, geom_geojson, source_sheet, source_edition, geometry_precise)
